import {findCrossings} from './interlacing.mjs';import {reconstructStitchTrace} from './stitch.mjs';self.onmessage=async e=>{const start=performance.now();try{const {derived,candidate}=e.data;let trace=e.data.trace;if(!e.data.knownResult&&derived.versions?.derivation==='stitch-derived-v1'&&!trace)trace=await reconstructStitchTrace(candidate.boundary,candidate.source,candidate.board,candidate.context,candidate.generation,derived);const result=e.data.knownResult||findCrossings(derived.strands,trace),markup=continuousWeaveSvg(derived.strands,result,e.data.settings,e.data.appearance,derived.provenanceFingerprint,candidate.boundary);self.postMessage({id:e.data.id,result,markup,workerMs:performance.now()-start});}catch(error){self.postMessage({id:e.data.id,error:error.message});}};